    /**
     * Render an Icon
     * @param string $name Icon Name
     * @param int $size Width and Height, In Pixels
     * @return string SVG markup
     */
    public static function svg(string $name, int $size = 16): string
    {
        $path = self::PATHS[$name] ?? self::PATHS[self::FALLBACK];
        $size = max(8, min(128, $size));

        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" width="%1$d" height="%1$d" viewBox="0 0 16 16"'
            . ' fill="currentColor" aria-hidden="true" focusable="false">%2$s</svg>',
            $size,
            $path
        );
    }

    /**
     * Whether an Icon Exists
     * @param string $name Icon Name
     * @return bool
     */
    public static function has(string $name): bool
    {
        return isset(self::PATHS[$name]);
    }

    /**
     * Every Icon Name
     * @return string[]
     */
    public static function names(): array
    {
        return array_keys(self::PATHS);
    }
}
